package eu.kanade.translation.engines.translator.fumeto

import io.kotest.matchers.shouldBe
import org.junit.jupiter.api.Test

/**
 * Pins the window planner against vectors generated by the reference
 * `run.py:windows` (budget 256), so the Kotlin port cannot drift from the
 * published page-mode behaviour: split points, neighbour widening, and the
 * single-window fast path.
 */
class FumetoPagePlannerTest {

    private fun windowsOf(vararg counts: Int) = FumetoPagePlanner.windows(intArrayOf(*counts), BUDGET)

    @Test
    fun `a page that fits the budget is a single window`() {
        windowsOf(3, 4, 2) shouldBe listOf(FumetoWindow(0, 3, 0, 3))
    }

    @Test
    fun `an empty page yields the degenerate single window`() {
        windowsOf() shouldBe listOf(FumetoWindow(0, 0, 0, 0))
    }

    @Test
    fun `long lines split with neighbour widening`() {
        windowsOf(120, 120, 120, 120) shouldBe listOf(
            FumetoWindow(0, 2, 0, 1),
            FumetoWindow(1, 3, 1, 2),
            FumetoWindow(2, 4, 2, 3),
            FumetoWindow(2, 4, 3, 4),
        )
    }

    @Test
    fun `mixed line counts split exactly like the reference`() {
        windowsOf(10, 100, 90, 5, 40, 60, 70, 3) shouldBe listOf(
            FumetoWindow(0, 5, 0, 2),
            FumetoWindow(0, 5, 2, 4),
            FumetoWindow(3, 8, 4, 6),
            FumetoWindow(3, 8, 6, 8),
        )
    }

    @Test
    fun `two maximal lines still fit one window`() {
        windowsOf(126, 126) shouldBe listOf(FumetoWindow(0, 2, 0, 2))
    }

    @Test
    fun `a long page widens windows with neighbouring lines`() {
        windowsOf(60, 60, 60, 60, 60, 60, 60) shouldBe listOf(
            FumetoWindow(0, 4, 0, 2),
            FumetoWindow(1, 5, 2, 4),
            FumetoWindow(3, 7, 4, 6),
            FumetoWindow(3, 7, 6, 7),
        )
    }

    @Test
    fun `one oversized line surrounded by small lines stays one window`() {
        windowsOf(5, 200, 5, 5, 5, 5) shouldBe listOf(FumetoWindow(0, 6, 0, 6))
    }

    private companion object {
        const val BUDGET = 256
    }
}
